{
  "name": "ssg",
  "version": "1.0.0",
  "description": "Static site generator CLI",
  "main": "dist/index.js",
  "bin": {
    "ssg": "./dist/cli.js"
  },
  "scripts": {
    "build": "tsc",
    "test": "vitest run",
    "test:watch": "vitest",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "chokidar": "^3.6.0",
    "commander": "^12.1.0",
    "gray-matter": "^4.0.3",
    "handlebars": "^4.7.8",
    "highlight.js": "^11.10.0",
    "marked": "^14.1.0",
    "ws": "^8.18.0"
  },
  "devDependencies": {
    "@types/node": "^22.5.0",
    "typescript": "^5.5.0",
    "vitest": "^2.0.0"
  }
}

export interface Frontmatter {
  title: string;
  date?: Date;
  tags?: string[];
  draft?: boolean;
  [key: string]: unknown;
}

export interface Page {
  frontmatter: Frontmatter;
  content: string;
  html: string;
  raw: string;
  slug: string;
  sourcePath: string;
  outputPath: string;
}

export interface SSGConfig {
  source: string;
  templates: string;
  output: string;
  siteTitle: string;
  siteUrl: string;
  siteDescription: string;
}

export interface TagData {
  tag: string;
  pages: Page[];
}

export interface TemplateContext {
  site: {
    title: string;
    url: string;
    description: string;
  };
  page?: Page;
  pages: Page[];
  tags: TagData[];
  currentTag?: string;
}

import matter from "gray-matter";
import { Frontmatter } from "./types.js";

export function parseFrontmatter(raw: string): {
  frontmatter: Frontmatter;
  content: string;
} {
  const parsed = matter(raw);
  const fm = parsed.data as Frontmatter;

  if (fm.date && typeof fm.date === "string") {
    fm.date = new Date(fm.date);
  }
  if (typeof fm.tags === "string") {
    fm.tags = fm.tags.split(",").map((t) => t.trim()).filter(Boolean);
  }
  if (!fm.tags) {
    fm.tags = [];
  }
  if (typeof fm.draft !== "boolean") {
    fm.draft = fm.draft === "true" || fm.draft === true;
  }

  return { frontmatter: fm, content: parsed.content };
}

import Handlebars from "handlebars";
import * as fs from "node:fs";
import * as path from "node:path";
import { TemplateContext } from "./types.js";

export function registerPartials(partialsDir: string): void {
  if (!fs.existsSync(partialsDir)) return;
  for (const entry of fs.readdirSync(partialsDir)) {
    const fullPath = path.join(partialsDir, entry);
    if (fs.statSync(fullPath).isFile() && entry.endsWith(".hbs")) {
      const name = path.basename(entry, ".hbs");
      const source = fs.readFileSync(fullPath, "utf-8");
      Handlebars.registerPartial(name, source);
    }
  }
}

export function render(
  templatePath: string,
  layoutsDir: string,
  context: TemplateContext
): string {
  const templateSource = fs.readFileSync(templatePath, "utf-8");
  const template = Handlebars.compile(templateSource);
  const body = template(context);

  const layoutName = (body.match(/^{{#layout\s+"([^"]+)"}}/) ?? [])[1];
  if (layoutName) {
    const resolved = body.replace(/^{{#layout\s+"[^"]+"}}\s*/s, "");
    const layoutPath = path.join(layoutsDir, `${layoutName}.hbs`);
    if (fs.existsSync(layoutPath)) {
      const layoutSource = fs.readFileSync(layoutPath, "utf-8");
      const layoutTemplate = Handlebars.compile(layoutSource);
      return layoutTemplate({ ...context, body: resolved });
    }
  }

  return body;
}

export function escapeHtml(str: string): string {
  return new Handlebars.SafeString(str).toString();
}

import { Page, TagData } from "./types.js";

export function buildTagIndex(pages: Page[]): TagData[] {
  const map = new Map<string, Page[]>();
  for (const page of pages) {
    for (const tag of page.frontmatter.tags ?? []) {
      if (!map.has(tag)) map.set(tag, []);
      map.get(tag)!.push(page);
    }
  }
  return Array.from(map.entries())
    .map(([tag, pages]) => ({ tag, pages }))
    .sort((a, b) => a.tag.localeCompare(b.tag));
}

import { Page, SSGConfig } from "./types.js";

export function generateRssXml(config: SSGConfig, pages: Page[]): string {
  const published = pages
    .filter((p) => !p.frontmatter.draft && p.frontmatter.date)
    .sort(
      (a, b) =>
        (b.frontmatter.date?.getTime() ?? 0) -
        (a.frontmatter.date?.getTime() ?? 0)
    )
    .slice(0, 20);

  const items = published
    .map((p) => {
      const date = p.frontmatter.date!;
      const rfc822 = date.toUTCString();
      const url = `${config.siteUrl}/${p.slug}.html`;
      return `    <item>
      <title>${escapeXml(p.frontmatter.title)}</title>
      <link>${escapeXml(url)}</link>
      <guid>${escapeXml(url)}</guid>
      <pubDate>${rfc822}</pubDate>
      <description>${escapeXml(p.html.slice(0, 500))}</description>
    </item>`;
    })
    .join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(config.siteTitle)}</title>
    <link>${escapeXml(config.siteUrl)}</link>
    <description>${escapeXml(config.siteDescription)}</description>
    <atom:link href="${escapeXml(config.siteUrl)}/rss.xml" rel="self" type="application/rss+xml"/>
${items}
  </channel>
</rss>`;
}

function escapeXml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

import hljs from "highlight.js";
import { Marked } from "marked";

const marked = new Marked({
  async: false,
  highlight(code: string, lang: string): string {
    if (lang && hljs.getLanguage(lang)) {
      try {
        return hljs.highlight(code, { language: lang }).value;
      } catch {
        return code;
      }
    }
    return hljs.highlightAuto(code).value;
  },
});

export function markdownToHtml(markdown: string): string {
  return marked.parse(markdown) as string;
}

import { WebSocketServer, WebSocket } from "ws";
import * as http from "node:http";
import * as fs from "node:fs";
import * as path from "node:path";
import chokidar from "chokidar";

const RELOAD_SCRIPT = `
<script>
(function() {
  var ws = new WebSocket('ws://localhost:__PORT__');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') location.reload();
  };
  ws.onclose = function() {
    setTimeout(function() {
      window.location.reload();
    }, 2000);
  };
})();
</script>
`;

export function injectReloadScript(html: string, port: number): string {
  const script = RELOAD_SCRIPT.replace("__PORT__", String(port));
  if (html.includes("</body>")) {
    return html.replace("</body>", script + "</body>");
  }
  return html + script;
}

const MIME: Record<string, string> = {
  ".html": "text/html",
  ".css": "text/css",
  ".js": "application/javascript",
  ".json": "application/json",
  ".png": "image/png",
  ".jpg": "image/jpeg",
  ".svg": "image/svg+xml",
  ".ico": "image/x-icon",
  ".xml": "application/xml",
};

function serveFile(
  filePath: string,
  res: http.ServerResponse
): void {
  try {
    const stat = fs.statSync(filePath);
    if (stat.isDirectory()) {
      const indexPath = path.join(filePath, "index.html");
      if (fs.existsSync(indexPath)) {
        filePath = indexPath;
      } else {
        res.writeHead(404);
        res.end("Not Found");
        return;
      }
    }
    const ext = path.extname(filePath).toLowerCase();
    const contentType = MIME[ext] || "application/octet-stream";
    const content = fs.readFileSync(filePath);
    res.writeHead(200, { "Content-Type": contentType });
    res.end(content);
  } catch {
    res.writeHead(404);
    res.end("Not Found");
  }
}

export function startDevServer(
  outputDir: string,
  sourceDir: string,
  templateDir: string,
  port: number,
  rebuild: () => Promise<void>
): void {
  const wss = new WebSocketServer({ port: port + 1 });
  let clients: WebSocket[] = [];

  wss.on("connection", (ws) => {
    clients.push(ws);
    ws.on("close", () => {
      clients = clients.filter((c) => c !== ws);
    });
  });

  function broadcastReload(): void {
    for (const client of clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send("reload");
      }
    }
  }

  const server = http.createServer((req, res) => {
    const urlPath = req.url === "/" ? "/index.html" : req.url ?? "/";
    const filePath = path.join(outputDir, urlPath);
    serveFile(filePath, res);
  });

  server.listen(port, () => {
    const liveReloadPort = port + 1;
    process.stdout.write(
      `Dev server running at http://localhost:${port}\nLive reload on ws://localhost:${liveReloadPort}\n`
    );
  });

  const watcher = chokidar.watch(
    [sourceDir, templateDir],
    {
      ignoreInitial: true,
      awaitWriteFinish: { stabilityThreshold: 200, pollInterval: 50 },
    }
  );

  watcher.on("all", async (_event: string, _filePath: string) => {
    try {
      await rebuild();
      broadcastReload();
      process.stdout.write(`Rebuilt at ${new Date().toLocaleTimeString()}\n`);
    } catch (err) {
      process.stderr.write(`Build error: ${err}\n`);
    }
  });
}

import * as fs from "node:fs";
import * as path from "node:path";
import { Page, SSGConfig, TemplateContext } from "./types.js";
import { parseFrontmatter } from "./frontmatter.js";
import { registerPartials, render } from "./renderer.js";
import { markdownToHtml } from "./highlight.js";
import { buildTagIndex } from "./tags.js";
import { generateRssXml } from "./rss.js";

export async function build(config: SSGConfig): Promise<void> {
  fs.mkdirSync(config.output, { recursive: true });

  registerPartials(path.join(config.templates, "partials"));

  const pages = collectPages(config.source);

  const tagData = buildTagIndex(pages);

  const baseContext: TemplateContext = {
    site: {
      title: config.siteTitle,
      url: config.siteUrl,
      description: config.siteDescription,
    },
    pages,
    tags: tagData,
  };

  const pageTemplate = path.join(config.templates, "page.hbs");

  for (const page of pages) {
    const ctx: TemplateContext = { ...baseContext, page };
    const html = render(pageTemplate, path.join(config.templates, "layouts"), ctx);
    const outPath = path.join(config.output, page.outputPath);
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, html, "utf-8");
  }

  const indexTemplate = path.join(config.templates, "index.hbs");
  if (fs.existsSync(indexTemplate)) {
    const html = render(
      indexTemplate,
      path.join(config.templates, "layouts"),
      baseContext
    );
    fs.writeFileSync(path.join(config.output, "index.html"), html, "utf-8");
  }

  const tagTemplate = path.join(config.templates, "tag.hbs");
  if (fs.existsSync(tagTemplate)) {
    const tagsDir = path.join(config.output, "tags");
    fs.mkdirSync(tagsDir, { recursive: true });
    for (const td of tagData) {
      const ctx: TemplateContext = { ...baseContext, currentTag: td.tag, page: undefined };
      const html = render(
        tagTemplate,
        path.join(config.templates, "layouts"),
        ctx
      );
      const safe = td.tag.replace(/[^a-zA-Z0-9-]/g, "-").toLowerCase();
      fs.writeFileSync(path.join(tagsDir, `${safe}.html`), html, "utf-8");
    }
  }

  const rss = generateRssXml(config, pages);
  fs.writeFileSync(path.join(config.output, "rss.xml"), rss, "utf-8");

  const css = `pre code.hljs{display:block;overflow-x:auto;padding:1em}code.hljs{padding:3px 5px}.hljs{background:#1e1e1e;color:#dcdcdc}.hljs-keyword,.hljs-literal,.hljs-symbol,.hljs-name{color:#569cd6}.hljs-type,.hljs-number{color:#b5cea8}.hljs-string{color:#d69d85}.hljs-comment{color:#6a9955}.hljs-meta{color:#9b9b9b}.hljs-attr,.hljs-built_in,.hljs-selector-tag,.hljs-title{color:#dcdcdc}`;
  fs.writeFileSync(path.join(config.output, "style.css"), css, "utf-8");
}

function collectPages(sourceDir: string): Page[] {
  const pages: Page[] = [];
  walk(sourceDir, (filePath) => {
    if (path.extname(filePath) !== ".md") return;
    const raw = fs.readFileSync(filePath, "utf-8");
    const { frontmatter, content } = parseFrontmatter(raw);
    const html = markdownToHtml(content);
    const relPath = path.relative(sourceDir, filePath);
    const slug = relPath.replace(/\.md$/, "").replace(/\\/g, "/");
    pages.push({
      frontmatter,
      content,
      html,
      raw,
      slug,
      sourcePath: filePath,
      outputPath: `${slug}.html`,
    });
  });
  return pages;
}

function walk(dir: string, fn: (filePath: string) => void): void {
  for (const entry of fs.readdirSync(dir)) {
    const full = path.join(dir, entry);
    if (fs.statSync(full).isDirectory()) {
      walk(full, fn);
    } else {
      fn(full);
    }
  }
}

#!/usr/bin/env node
import { Command } from "commander";
import * as path from "node:path";
import { build } from "./index.js";
import { injectReloadScript, startDevServer } from "./server.js";
import * as fs from "node:fs";
import { SSGConfig } from "./types.js";

const program = new Command();

program
  .name("ssg")
  .description("Static site generator from Markdown with Handlebars templates")
  .version("1.0.0")
  .requiredOption("-s, --source <dir>", "Source directory of Markdown files")
  .requiredOption("-t, --templates <dir>", "Template directory of Handlebars files")
  .requiredOption("-o, --output <dir>", "Output directory for generated HTML")
  .option("--site-title <title>", "Site title", "My Site")
  .option("--site-url <url>", "Site base URL", "https://example.com")
  .option("--site-description <desc>", "Site description", "A static site")
  .option("-p, --port <number>", "Dev server port", "3000")
  .option("--serve", "Start dev server with live reload", false)
  .action(async (opts) => {
    const config: SSGConfig = {
      source: path.resolve(opts.source),
      templates: path.resolve(opts.templates),
      output: path.resolve(opts.output),
      siteTitle: opts.siteTitle,
      siteUrl: opts.siteUrl,
      siteDescription: opts.siteDescription,
    };

    if (opts.serve) {
      await build(config);

      const injectReload = (dir: string): void => {
        for (const entry of fs.readdirSync(dir, { recursive: true })) {
          const full = path.join(dir, entry as string);
          if (
            fs.statSync(full).isFile() &&
            (entry as string).endsWith(".html")
          ) {
            const html = fs.readFileSync(full, "utf-8");
            const rewritten = injectReloadScript(html, parseInt(opts.port, 10) + 1);
            fs.writeFileSync(full, rewritten, "utf-8");
          }
        }
      };

      injectReload(config.output);

      startDevServer(
        config.output,
        config.source,
        config.templates,
        parseInt(opts.port, 10),
        async () => {
          await build(config);
          injectReload(config.output);
        }
      );
    } else {
      await build(config);
      process.stdout.write(`Site built to ${config.output}\n`);
    }
  });

program.parse();

